mkdir -p /app/output && cat > /app/output/index.html <<'HTML'
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>DeployCloud Blog — Discover the latest in web development</title>
  <meta name="description" content="A tech blog showcasing engineering insights, product updates, and community stories from a cloud deployment platform." />
  <style>
    :root {
      --bg: #f6f8fb;
      --surface: #ffffff;
      --text: #0b1220;
      --muted: #51607a;
      --line: #e4e9f2;
      --accent: #2f6df6;
      --accent-soft: #e8efff;
      --shadow: 0 10px 30px rgba(9, 20, 45, 0.08);
      --radius: 14px;
      --radius-sm: 999px;
      --container: 1200px;
    }

    * { box-sizing: border-box; }
    body {
      margin: 0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
      background: var(--bg);
      color: var(--text);
      line-height: 1.6;
    }

    a { color: inherit; text-decoration: none; }

    .container {
      width: min(var(--container), calc(100% - 2rem));
      margin-inline: auto;
    }

    header {
      position: sticky;
      top: 0;
      z-index: 40;
      background: rgba(246, 248, 251, 0.92);
      backdrop-filter: saturate(180%) blur(10px);
      border-bottom: 1px solid var(--line);
    }

    .topbar {
      height: 76px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
    }

    .brand {
      font-size: 1.15rem;
      font-weight: 800;
      letter-spacing: -0.02em;
    }

    .brand span { color: var(--accent); }

    .nav {
      display: flex;
      align-items: center;
      gap: 1.25rem;
      position: relative;
    }

    .nav-link,
    .dropdown-trigger {
      font-size: 0.95rem;
      color: #22304a;
      font-weight: 600;
      background: none;
      border: 0;
      cursor: pointer;
      padding: 0.4rem 0.2rem;
    }

    .dropdown {
      position: relative;
    }

    .mega {
      position: absolute;
      top: calc(100% + 12px);
      left: 50%;
      transform: translateX(-50%);
      min-width: 620px;
      background: var(--surface);
      border: 1px solid var(--line);
      border-radius: 16px;
      box-shadow: var(--shadow);
      display: none;
      grid-template-columns: repeat(3, 1fr);
      gap: 1rem;
      padding: 1rem;
    }

    .mega.open { display: grid; }

    .mega-col {
      padding: 0.5rem;
      border-radius: 12px;
    }

    .mega-col h4 {
      margin: 0 0 0.5rem;
      font-size: 0.85rem;
      color: #5f6e89;
      text-transform: uppercase;
      letter-spacing: 0.08em;
    }

    .mega-col a {
      display: block;
      padding: 0.42rem 0;
      font-size: 0.93rem;
      color: #1a2740;
    }

    .mega-col a:hover { color: var(--accent); }

    .hero {
      padding: 3rem 0 1rem;
    }

    .hero h1 {
      margin: 0;
      font-size: clamp(2rem, 3.2vw, 3.1rem);
      letter-spacing: -0.03em;
      line-height: 1.1;
      max-width: 850px;
    }

    .hero p {
      margin: 1rem 0 0;
      color: var(--muted);
      font-size: 1.08rem;
      max-width: 760px;
    }

    .filters {
      margin-top: 1.8rem;
      display: flex;
      gap: 0.8rem;
      flex-wrap: wrap;
      align-items: center;
    }

    .pill {
      border: 1px solid var(--line);
      background: var(--surface);
      color: #26334d;
      height: 42px;
      padding: 0 1rem;
      border-radius: var(--radius-sm);
      font-weight: 600;
      cursor: pointer;
      transition: all 0.2s ease;
    }

    .pill:hover { border-color: #cdd8ec; }

    .pill.active {
      background: var(--accent-soft);
      border-color: #c7d8ff;
      color: #1244b8;
    }

    .search-wrap {
      margin-left: auto;
      min-width: min(100%, 320px);
      position: relative;
    }

    .search-wrap input {
      width: 100%;
      height: 44px;
      border-radius: 12px;
      border: 1px solid var(--line);
      padding: 0 0.95rem;
      font-size: 0.95rem;
      background: #fff;
      color: var(--text);
    }

    .search-wrap input:focus {
      outline: 2px solid #b8ccfb;
      border-color: #b8ccfb;
    }

    section { padding: 1.5rem 0; }

    .section-head {
      display: flex;
      align-items: baseline;
      justify-content: space-between;
      margin-bottom: 0.9rem;
      gap: 1rem;
    }

    .section-head h2 {
      margin: 0;
      font-size: 1.5rem;
      letter-spacing: -0.02em;
    }

    .section-head p {
      margin: 0;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .featured-grid {
      display: grid;
      grid-template-columns: 1.35fr 1fr 1fr;
      gap: 1rem;
    }

    .card {
      background: var(--surface);
      border: 1px solid var(--line);
      border-radius: var(--radius);
      padding: 1rem;
      box-shadow: 0 2px 8px rgba(16, 29, 60, 0.04);
      transition: transform 0.2s ease, box-shadow 0.2s ease;
      display: flex;
      flex-direction: column;
      min-height: 100%;
    }

    .card:hover {
      transform: translateY(-3px);
      box-shadow: var(--shadow);
    }

    .featured-primary {
      background: linear-gradient(140deg, #ffffff 0%, #f0f5ff 100%);
      border-color: #d7e3ff;
      padding: 1.2rem;
    }

    .tag {
      display: inline-flex;
      align-items: center;
      height: 27px;
      padding: 0 0.72rem;
      border-radius: 999px;
      font-size: 0.75rem;
      font-weight: 700;
      letter-spacing: 0.04em;
      text-transform: uppercase;
      background: #eef3ff;
      color: #2451c7;
      width: fit-content;
    }

    .meta {
      margin-top: 0.7rem;
      font-size: 0.82rem;
      color: #62708c;
    }

    h3 {
      margin: 0.5rem 0 0;
      font-size: 1.35rem;
      line-height: 1.25;
      letter-spacing: -0.02em;
    }

    .card p {
      margin: 0.7rem 0 0;
      color: #475571;
      font-size: 0.96rem;
    }

    .author {
      margin-top: auto;
      padding-top: 1rem;
      display: flex;
      align-items: center;
      gap: 0.6rem;
      font-size: 0.84rem;
      color: #5a6987;
    }

    .avatar {
      width: 28px;
      height: 28px;
      border-radius: 50%;
      display: inline-grid;
      place-items: center;
      background: #dbe6ff;
      color: #214ebf;
      font-weight: 700;
      font-size: 0.75rem;
    }

    .stats {
      margin-top: 0.9rem;
      display: grid;
      grid-template-columns: 1fr;
      gap: 0.45rem;
    }

    .stat {
      font-size: 0.88rem;
      background: rgba(47, 109, 246, 0.08);
      border: 1px solid rgba(47, 109, 246, 0.15);
      color: #1b3f9e;
      border-radius: 10px;
      padding: 0.5rem 0.6rem;
    }

    .news-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
    }

    .cta {
      margin-top: 1rem;
      background: linear-gradient(135deg, #0f1a2f 0%, #1e3566 100%);
      color: #f4f7ff;
      border-radius: 16px;
      padding: 1.4rem;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      border: 1px solid #243d72;
    }

    .cta h3 { margin: 0; color: #fff; font-size: 1.3rem; }
    .cta p { margin: 0.5rem 0 0; color: #c7d6ff; }

    .cta a {
      white-space: nowrap;
      background: #fff;
      color: #0f1a2f;
      font-weight: 700;
      padding: 0.7rem 1rem;
      border-radius: 10px;
    }

    .show-more-wrap {
      margin-top: 1.1rem;
      display: flex;
      justify-content: center;
    }

    .show-more {
      border: 1px solid #b7c7e6;
      background: #fff;
      color: #193367;
      font-weight: 700;
      border-radius: 10px;
      height: 46px;
      padding: 0 1.2rem;
      cursor: pointer;
    }

    .show-more:hover { border-color: #8ba7df; }

    .empty {
      display: none;
      text-align: center;
      margin: 1rem 0;
      padding: 1rem;
      border: 1px dashed #c8d4ec;
      border-radius: 12px;
      color: #5b6a87;
      background: #fbfcff;
    }

    footer {
      margin-top: 2rem;
      border-top: 1px solid var(--line);
      padding: 1.5rem 0 2.5rem;
      color: #556581;
      font-size: 0.9rem;
      background: #f3f6fc;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: 1.5fr repeat(3, 1fr);
      gap: 1rem;
    }

    .footer-col h4 {
      margin: 0 0 0.5rem;
      font-size: 0.85rem;
      color: #2d3b57;
    }

    .footer-col a {
      display: block;
      margin: 0.35rem 0;
      color: #5c6d8a;
      font-size: 0.88rem;
    }

    @media (max-width: 1100px) {
      .featured-grid { grid-template-columns: 1fr 1fr; }
      .featured-primary { grid-column: 1 / -1; }
      .news-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
      .mega { min-width: 540px; }
      .footer-grid { grid-template-columns: repeat(2, 1fr); }
    }

    @media (max-width: 780px) {
      .topbar { height: auto; padding: 0.8rem 0; flex-wrap: wrap; }
      .nav { width: 100%; justify-content: space-between; gap: 0.5rem; flex-wrap: wrap; }
      .mega {
        position: static;
        transform: none;
        min-width: 100%;
        margin-top: 0.6rem;
      }
      .filters { align-items: stretch; }
      .search-wrap { margin-left: 0; width: 100%; }
      .featured-grid, .news-grid { grid-template-columns: 1fr; }
      .cta { flex-direction: column; align-items: flex-start; }
      .footer-grid { grid-template-columns: 1fr; }
    }
  </style>
</head>
<body>
  <header>
    <div class="container topbar">
      <a href="index.html" class="brand">Deploy<span>Cloud</span></a>
      <nav class="nav" aria-label="Main navigation">
        <div class="dropdown" data-dropdown="products">
          <button class="dropdown-trigger" aria-expanded="false">Products ▾</button>
          <div class="mega" role="menu" aria-label="Products menu">
            <div class="mega-col">
              <h4>AI Cloud</h4>
              <a href="#">AI Gateway</a>
