    .show-more:hover { border-color: #8ba7df; }

    .empty {
      display: none;
      text-align: center;
      margin: 1rem 0;
      padding: 1rem;
      border: 1px dashed #c8d4ec;
      border-radius: 12px;
      color: #5b6a87;
